"""Deterministic domain identity (FND-001).

ID rules
--------
* RawNoteEvent IDs are unique within one transcription revision:
  ``rne-<zero-padded ordinal>`` allocated in backend output order.
* Canonical score note IDs are unique within one score revision:
  ``sn-<zero-padded ordinal>`` allocated in score order.
* Score revision IDs are content-derived: ``rev-<sha256[:16]>`` over the
  canonical serialized payload, so identical content + settings always
  produces the identical revision ID.
* Concert and Horn in F presentations share the *same* canonical note ID;
  presentation IDs (e.g. Verovio element IDs) are never domain IDs.
* MusicXML ``note/@id`` values are deterministic export IDs derived from
  ``(score_revision, canonical_note_id)`` via :func:`musicxml_note_id`.
* When notation engraving splits one canonical note into several tied
  ``<note>`` fragments (barline splits, complex durations), fragment ``k > 1``
  carries the suffixed ID ``hs-sn-<6 digits>-k`` so every emitted ``note/@id``
  remains a document-unique ``xs:ID`` while still resolving to the same
  canonical note via :func:`canonical_note_id_from_musicxml`.
* MusicXML rest ``<note>`` elements carry presentation-only IDs
  ``hs-rest-<6 digits>``; they never map back to canonical notes.
"""

from __future__ import annotations

import hashlib
import json
import re
from typing import NewType

RawNoteEventId = NewType("RawNoteEventId", str)
ScoreNoteId = NewType("ScoreNoteId", str)
ScoreRevisionId = NewType("ScoreRevisionId", str)
TranscriptionRevisionId = NewType("TranscriptionRevisionId", str)
ProjectId = NewType("ProjectId", str)

_RAW_RE = re.compile(r"^rne-\d{6}$")
_SCORE_NOTE_RE = re.compile(r"^sn-\d{6}$")
_REVISION_RE = re.compile(r"^rev-[0-9a-f]{16}$")
_TRANSCRIPTION_RE = re.compile(r"^tr-[0-9a-f]{16}$")
_PROJECT_RE = re.compile(r"^prj-[0-9a-f]{16}$")
_MUSICXML_NOTE_RE = re.compile(r"^hs-sn-\d{6}(?:-\d+)?$")
_MUSICXML_REST_RE = re.compile(r"^hs-rest-\d{6}$")


def is_raw_note_event_id(value: str) -> bool:
    return bool(_RAW_RE.match(value))


def is_score_note_id(value: str) -> bool:
    return bool(_SCORE_NOTE_RE.match(value))


def is_score_revision_id(value: str) -> bool:
    return bool(_REVISION_RE.match(value))


def is_transcription_revision_id(value: str) -> bool:
    return bool(_TRANSCRIPTION_RE.match(value))


def is_project_id(value: str) -> bool:
    return bool(_PROJECT_RE.match(value))


def is_musicxml_note_id(value: str) -> bool:
    return bool(_MUSICXML_NOTE_RE.match(value))


def is_musicxml_rest_id(value: str) -> bool:
    return bool(_MUSICXML_REST_RE.match(value))


def _digest(payload: object) -> str:
    """Stable SHA-256 over a canonical JSON encoding of *payload*."""
    blob = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    return hashlib.sha256(blob.encode("utf-8")).hexdigest()


def derive_project_id(seed: object) -> ProjectId:
    """Derive a deterministic project ID from creation-time seed data."""
    return ProjectId(f"prj-{_digest(seed)[:16]}")


def derive_transcription_revision_id(payload: object) -> TranscriptionRevisionId:
    """Content-derived transcription revision ID (backend + settings + audio hash)."""
    return TranscriptionRevisionId(f"tr-{_digest(payload)[:16]}")


def derive_score_revision_id(payload: object) -> ScoreRevisionId:
    """Content-derived score revision ID.

    Re-quantization with different settings/content yields a new revision ID;
    identical input always yields the identical ID.
    """
    return ScoreRevisionId(f"rev-{_digest(payload)[:16]}")


def musicxml_note_id(note_id: ScoreNoteId, fragment: int = 1) -> str:
    """Deterministic MusicXML ``note/@id`` for a canonical score note.

    The mapping is a pure function of the canonical note ID so a rendered
    element can always be traced back to domain identity:
    ``hs-sn-000042`` -> ``sn-000042``.

    ``fragment`` is the 1-based ordinal of the emitted ``<note>`` element
    when engraving splits the canonical note into tied fragments (barline
    or complex-duration splits). Fragment 1 carries the canonical export
    ID ``hs-sn-<6 digits>``; fragments 2+ carry ``hs-sn-<6 digits>-<k>`` so
    every ``note/@id`` stays a document-unique ``xs:ID``.
    """
    if not is_score_note_id(note_id):
        raise ValueError(f"not a canonical score note id: {note_id!r}")
    if fragment < 1:
        raise ValueError(f"fragment must be >= 1, got {fragment}")
    if fragment == 1:
        return f"hs-{note_id}"
    return f"hs-{note_id}-{fragment}"


def canonical_note_id_from_musicxml(export_id: str) -> ScoreNoteId:
    """Inverse of :func:`musicxml_note_id`.

    Accepts both ``hs-sn-<6 digits>`` and the tied-fragment form
    ``hs-sn-<6 digits>-<k>``; a fragment ID resolves to the canonical note
    it was split from.
    """
    if not is_musicxml_note_id(export_id):
        raise ValueError(f"not a HornScribe MusicXML note id: {export_id!r}")
    match = re.match(r"^hs-(sn-\d{6})", export_id)
    assert match is not None  # guaranteed by is_musicxml_note_id
    return ScoreNoteId(match.group(1))


def musicxml_rest_id(ordinal: int) -> str:
    """Presentation-only ID for a rest ``<note>`` element.

    Rests have no canonical identity; the ID exists so every emitted
    ``<note>`` element carries a deterministic, document-unique ``xs:ID``
    (``hs-rest-<6 digits>``).
    """
    if ordinal < 1:
        raise ValueError(f"ordinal must be >= 1, got {ordinal}")
    return f"hs-rest-{ordinal:06d}"


class IdAllocator:
    """Allocates sequential deterministic IDs inside one revision scope."""

    def __init__(self, prefix: str) -> None:
        if prefix not in ("rne", "sn"):
            raise ValueError(f"unknown id prefix: {prefix!r}")
        self._prefix = prefix
        self._next = 1

    def allocate(self) -> str:
        value = f"{self._prefix}-{self._next:06d}"
        self._next += 1
        return value

    def allocate_raw_event_id(self) -> RawNoteEventId:
        if self._prefix != "rne":
            raise TypeError("allocator prefix is not 'rne'")
        return RawNoteEventId(self.allocate())

    def allocate_score_note_id(self) -> ScoreNoteId:
        if self._prefix != "sn":
            raise TypeError("allocator prefix is not 'sn'")
        return ScoreNoteId(self.allocate())

"""ScoreDocument -> MusicXML 4.0 export (ENG-001; master plan §11, dev plan §13).

Pipeline::

    ScoreDocument -> music21 score -> MusicXML -> validate/patch -> final MusicXML

music21 carries the engraving-level details; HornScribe then normalizes the
emitted tree so exported documents are deterministic and identity-bearing:

* every pitched ``<note>`` carries ``id="hs-sn-*"`` via
  :func:`musicxml_note_id` — when engraving splits a canonical note into
  tied fragments, fragment ``k`` gets ``hs-sn-<id>-k`` so all ``xs:ID``
  values stay document-unique;
* rest ``<note>`` elements carry presentation IDs ``hs-rest-*``;
* ``score-part``/``part``/``score-instrument``/``midi-instrument`` IDs are
  normalized to deterministic ``P1..``/``I1..`` (music21 generates random
  ones);
* volatile ``<encoding-date>`` is removed so identical input yields
  byte-identical output;
* Horn in F parts carry written pitches *and*
  ``<transpose><diatonic>-4</diatonic><chromatic>-7</chromatic></transpose>``
  (MusicXML transpose is written -> sounding, i.e. -P5).
"""

from __future__ import annotations

import xml.etree.ElementTree as ET
from dataclasses import dataclass
from pathlib import Path

from music21.musicxml.m21ToXml import GeneralObjectExporter

from hornscribe.domain.ids import (
    ScoreNoteId,
    canonical_note_id_from_musicxml,
    is_musicxml_note_id,
    musicxml_note_id,
    musicxml_rest_id,
)
from hornscribe.domain.score import PitchSpace, ScoreDocument
from hornscribe.instruments import horn_f
from hornscribe.notation.to_music21 import build_music21_score

_XML_DECL = '<?xml version="1.0" encoding="utf-8"?>'
_MUSICXML_DOCTYPE = (
    '<!DOCTYPE score-partwise PUBLIC "-//Recordare//DTD MusicXML 4.0 Partwise//EN" '
    '"http://www.musicxml.org/dtds/partwise.dtd">'
)


class ExportError(RuntimeError):
    """Export produced XML that violates HornScribe invariants."""


# ---------------------------------------------------------------------------
# export API
# ---------------------------------------------------------------------------


def export_musicxml(
    score: ScoreDocument,
    presentation: PitchSpace = PitchSpace.CONCERT,
) -> str:
    """Export *score* as a MusicXML 4.0 string.

    ``CONCERT`` emits sounding pitches with no transposition metadata;
    ``WRITTEN_HORN_F`` emits written (+P5) pitches with the Horn in F
    ``<transpose>`` element so a reader recovers sounding pitch.
    """
    m21_score = build_music21_score(score, presentation)
    raw = GeneralObjectExporter().parse(m21_score)
    text = raw.decode("utf-8") if isinstance(raw, bytes) else str(raw)
    return _normalize_musicxml(text, presentation)


def export_concert_musicxml(score: ScoreDocument) -> str:
    """``concert.musicxml``: canonical sounding pitches, no transposition."""
    return export_musicxml(score, PitchSpace.CONCERT)


def export_horn_in_f_musicxml(score: ScoreDocument) -> str:
    """``horn_in_f.musicxml``: written +P5 pitches plus -P5 transpose metadata."""
    return export_musicxml(score, PitchSpace.WRITTEN_HORN_F)


def write_musicxml(
    score: ScoreDocument,
    path: Path,
    presentation: PitchSpace = PitchSpace.CONCERT,
) -> Path:
    """Write :func:`export_musicxml` output to *path* (UTF-8)."""
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(export_musicxml(score, presentation), encoding="utf-8", newline="\n")
    return path


# ---------------------------------------------------------------------------
# normalization / patching
# ---------------------------------------------------------------------------

_STEP_PC = {"C": 0, "D": 2, "E": 4, "F": 5, "G": 7, "A": 9, "B": 11}


def _normalize_musicxml(xml_text: str, presentation: PitchSpace) -> str:
    root = ET.fromstring(xml_text)
    if root.tag != "score-partwise":
        raise ExportError(f"expected score-partwise root, got {root.tag!r}")
    root.set("version", "4.0")

    _strip_volatile_metadata(root)
    _normalize_part_and_instrument_ids(root)
    _assign_note_ids(root)

    if presentation is PitchSpace.WRITTEN_HORN_F:
        for part_el in root.findall("part"):
            _ensure_horn_transpose(part_el)
    else:
        for part_el in root.findall("part"):
            _forbid_transpose(part_el)

    ET.indent(root, space="  ")
    body = ET.tostring(root, encoding="unicode")
    return f"{_XML_DECL}\n{_MUSICXML_DOCTYPE}\n{body}\n"


def _strip_volatile_metadata(root: ET.Element) -> None:
    """Remove content that would break byte-determinism (encoding-date)."""
    for encoding in root.iter("encoding"):
        for child in list(encoding):
            if child.tag == "encoding-date":
                encoding.remove(child)


def _normalize_part_and_instrument_ids(root: ET.Element) -> None:
    """Replace music21's random part/instrument IDs with deterministic ones."""
    part_list = root.find("part-list")
    if part_list is None:
        raise ExportError("MusicXML document has no part-list")
    score_parts = part_list.findall("score-part")
    id_map: dict[str, str] = {}
    inst_counter = 0
    for idx, sp in enumerate(score_parts, start=1):
        old = sp.get("id")
        new = f"P{idx}"
        if old is not None:
            id_map[old] = new
        sp.set("id", new)
        # midi-instrument/@id references its score-instrument/@id, so a
        # score-instrument/midi-instrument pair keeps one shared ID.
        per_part: dict[str, str] = {}
        for child in sp:
            if child.tag in ("score-instrument", "midi-instrument"):
                old_inst = child.get("id") or ""
                if old_inst not in per_part:
                    inst_counter += 1
                    per_part[old_inst] = f"I{inst_counter}"
                child.set("id", per_part[old_inst])

    for part_el in root.findall("part"):
        old = part_el.get("id")
        if old is None or old not in id_map:
            raise ExportError(f"part element has unknown id {old!r}")
        part_el.set("id", id_map[old])


def _assign_note_ids(root: ET.Element) -> None:
    """Ensure every ``<note>`` carries a deterministic, document-unique ID.

    music21 duplicates ``note.id`` across fragments it splits (barline or
    complex-duration splits).  Pitched fragments of one canonical note are
    emitted consecutively, so the k-th occurrence of an export ID is
    rewritten to the fragment form ``hs-sn-<id>-k``.  Rest and fragment
    counters are document-global because ``note/@id`` is an ``xs:ID`` and
    must be unique across the whole document.
    """
    counts: dict[ScoreNoteId, int] = {}
    rest_ordinal = 0
    for part_el in root.findall("part"):
        for note_el in part_el.iter("note"):
            if note_el.find("chord") is not None:
                raise ExportError("chord <note> elements are unsupported in MVP export")
            if note_el.find("rest") is not None:
                rest_ordinal += 1
                note_el.set("id", musicxml_rest_id(rest_ordinal))
                continue
            nid = note_el.get("id")
            if nid is None or not is_musicxml_note_id(nid):
                raise ExportError(f"pitched <note> missing HornScribe export id: {nid!r}")
            canonical = canonical_note_id_from_musicxml(nid)
            counts[canonical] = counts.get(canonical, 0) + 1
            note_el.set("id", musicxml_note_id(canonical, counts[canonical]))


def _ensure_horn_transpose(part_el: ET.Element) -> None:
    """Horn in F MusicXML must declare written -> sounding = -P5."""
    transpose = _first_transpose(part_el)
    expected = (
        str(horn_f.HORN_F_WRITTEN_TO_SOUNDING_DIATONIC),
        str(horn_f.HORN_F_WRITTEN_TO_SOUNDING_CHROMATIC),
    )
    if transpose is None:
        first_measure = part_el.find("measure")
        if first_measure is None:
            raise ExportError("horn part has no measures")
        attributes = first_measure.find("attributes")
        if attributes is None:
            attributes = ET.Element("attributes")
            first_measure.insert(0, attributes)
        transpose = ET.SubElement(attributes, "transpose")
        ET.SubElement(transpose, "diatonic").text = expected[0]
        ET.SubElement(transpose, "chromatic").text = expected[1]
        return
    diatonic = transpose.findtext("diatonic")
    chromatic = transpose.findtext("chromatic")
    if (diatonic, chromatic) != expected:
        raise ExportError(
            f"horn part transpose is diatonic={diatonic} chromatic={chromatic}, "
            f"expected {expected[0]}/{expected[1]}"
        )


def _forbid_transpose(part_el: ET.Element) -> None:
    transpose = _first_transpose(part_el)
    if transpose is None:
        return
    chromatic = transpose.findtext("chromatic")
    if chromatic not in (None, "0"):
        raise ExportError("concert export must not carry transposition metadata")


def _first_transpose(part_el: ET.Element) -> ET.Element | None:
    for measure in part_el.findall("measure"):
        attributes = measure.find("attributes")
        if attributes is not None:
            transpose = attributes.find("transpose")
            if transpose is not None:
                return transpose
    return None


# ---------------------------------------------------------------------------
# re-import helpers (round-trip verification)
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class ExportedNote:
    """One ``<note>`` element read back from exported MusicXML."""

    export_id: str
    part_id: str
    written_midi: int | None  # None for rests
    sounding_midi: int | None  # written + part <transpose chromatic>
    canonical_id: ScoreNoteId | None  # None for rests


def _midi_from_pitch_el(pitch_el: ET.Element) -> int:
    step = pitch_el.findtext("step")
    octave = pitch_el.findtext("octave")
    if step is None or octave is None:
        raise ExportError("pitched <note> without step/octave")
    alter = int(float(pitch_el.findtext("alter") or 0))
    return (int(octave) + 1) * 12 + _STEP_PC[step] + alter


def iter_exported_notes(xml_text: str) -> tuple[ExportedNote, ...]:
    """Parse exported MusicXML back into per-note sounding identity.

    ``sounding_midi`` applies the part's first ``<transpose>`` chromatic
    value to the written pitch, which is the MuseScore/Verovio playback
    interpretation.
    """
    root = ET.fromstring(xml_text)
    if root.tag != "score-partwise":
        raise ExportError(f"expected score-partwise root, got {root.tag!r}")
    out: list[ExportedNote] = []
    for part_el in root.findall("part"):
        transpose = _first_transpose(part_el)
        chromatic = int(transpose.findtext("chromatic") or 0) if transpose is not None else 0
        for note_el in part_el.iter("note"):
            export_id = note_el.get("id") or ""
            if note_el.find("rest") is not None:
                out.append(ExportedNote(export_id, part_el.get("id") or "", None, None, None))
                continue
            pitch_el = note_el.find("pitch")
            if pitch_el is None:
                raise ExportError("non-rest <note> without <pitch>")
            written = _midi_from_pitch_el(pitch_el)
            canonical = (
                canonical_note_id_from_musicxml(export_id)
                if is_musicxml_note_id(export_id)
                else None
            )
            out.append(
                ExportedNote(
                    export_id=export_id,
                    part_id=part_el.get("id") or "",
                    written_midi=written,
                    sounding_midi=written + chromatic,
                    canonical_id=canonical,
                )
            )
    return tuple(out)

"""Render a canonical :class:`ScoreDocument` into a music21 stream.

HornScribe domain objects stay authoritative; this module only *renders*
them into ``music21`` objects so that music21 can carry the engraving-level
MusicXML details (dev plan §13).  Every pitched ``music21`` note is tagged
with its deterministic MusicXML export ID (:func:`musicxml_note_id`) before
serialization, so emitted ``note/@id`` values always trace back to canonical
identity.

Responsibilities:

* measure construction from the canonical time signature / pickup beats
* splitting notes that cross barlines into tied fragments
* inserting rests for gaps inside measures
* written-pitch projection for the Horn in F presentation
  (``PitchSpace.WRITTEN_HORN_F``), including the transposed key signature
  and the ``instrument.Horn`` that produces ``<transpose>-4/-7`` metadata
* tempo map -> ``MetronomeMark`` placement

Non-responsibilities: enharmonic respelling beyond music21's defaults
(dev plan §11 keeps that as a later, user-adjustable stage).
"""

from __future__ import annotations

from dataclasses import dataclass
from fractions import Fraction

from music21 import clef, instrument, key, metadata, meter, note, pitch, stream, tempo, tie
from music21.stream import enums as stream_enums

from hornscribe.domain.ids import musicxml_note_id
from hornscribe.domain.score import (
    PitchSpace,
    QuantizedNote,
    ScoreDocument,
    ScoreRevisionPayload,
)
from hornscribe.instruments import horn_f


class NotationError(ValueError):
    """Canonical content that cannot be rendered into MVP notation."""


@dataclass(frozen=True)
class _MeasureSpan:
    """One measure's span in canonical beats."""

    number: int  # 0 = pickup measure (implicit), else 1-based
    start_beat: Fraction
    end_beat: Fraction
    implicit: bool = False

    @property
    def duration_beats(self) -> Fraction:
        return self.end_beat - self.start_beat


def _beat_ql(payload: ScoreRevisionPayload) -> Fraction:
    """Quarter-note length of one canonical beat."""
    return Fraction(4, payload.time_signature.beat_unit)


def _measure_length_beats(payload: ScoreRevisionPayload) -> Fraction:
    ts = payload.time_signature
    if ts.beats_per_measure <= 0 or ts.beat_unit <= 0:
        raise NotationError(f"invalid time signature: {ts.beats_per_measure}/{ts.beat_unit}")
    return Fraction(ts.beats_per_measure)


def _content_end_beat(payload: ScoreRevisionPayload) -> Fraction:
    end = payload.pickup_beats
    for part in payload.parts:
        for n in part.notes:
            end = max(end, n.start_beat + n.duration_beats)
    return end


def _measure_spans(payload: ScoreRevisionPayload) -> list[_MeasureSpan]:
    """Deterministic measure layout shared by every part.

    With ``pickup_beats > 0`` the first measure is number 0 (implicit) and
    spans ``[0, pickup)``; numbered measures then tile full bars.  Without a
    pickup, measures 1..N tile from beat 0.  Always emits at least one
    measure.
    """
    mlen = _measure_length_beats(payload)
    pickup = payload.pickup_beats
    if pickup < 0:
        raise NotationError(f"negative pickupBeats: {pickup}")
    end = _content_end_beat(payload)

    spans: list[_MeasureSpan] = []
    if pickup > 0:
        spans.append(_MeasureSpan(0, Fraction(0), pickup, implicit=True))
        if end <= pickup:
            return spans
        n_full = -(-(end - pickup) // mlen)  # ceil
        for k in range(1, int(n_full) + 1):
            start = pickup + (k - 1) * mlen
            spans.append(_MeasureSpan(k, start, start + mlen))
        return spans

    n_full = max(1, int(-(-end // mlen)))  # ceil, at least 1
    for k in range(1, n_full + 1):
        start = (k - 1) * mlen
        spans.append(_MeasureSpan(k, start, start + mlen))
    return spans


def _tie_for(piece_index: int, piece_count: int, note_: QuantizedNote) -> tie.Tie | None:
    """Tie for one emitted fragment of a canonical note.

    ``tie_stop`` on the canonical note = incoming tie on the *first*
    fragment; ``tie_start`` = outgoing tie on the *last* fragment.
    Fragments produced by barline splits tie to each other; interior
    fragments use ``continue`` (exported as stop+start).
    """
    tie_in = piece_index > 0 or note_.tie_stop
    tie_out = piece_index < piece_count - 1 or note_.tie_start
    if tie_in and tie_out:
        return tie.Tie("continue")
    if tie_in:
        return tie.Tie("stop")
    if tie_out:
        return tie.Tie("start")
    return None


def _note_pieces(
    note_: QuantizedNote, spans: list[_MeasureSpan]
) -> list[tuple[int, Fraction, Fraction]]:
    """Split a canonical note into ``(span_index, local_offset_beats, dur_beats)``."""
    start = note_.start_beat
    end = start + note_.duration_beats
    if start < 0 or note_.duration_beats <= 0:
        raise NotationError(
            f"note {note_.id} has invalid start/duration: {start}+{note_.duration_beats}"
        )
    pieces: list[tuple[int, Fraction, Fraction]] = []
    for idx, span in enumerate(spans):
        if span.end_beat <= start:
            continue
        if span.start_beat >= end:
            break
        piece_start = max(start, span.start_beat)
        piece_end = min(end, span.end_beat)
        if piece_end > piece_start:
            pieces.append((idx, piece_start - span.start_beat, piece_end - piece_start))
    if not pieces:
        raise NotationError(f"note {note_.id} does not overlap any measure")
    return pieces


def _check_monophonic(notes: tuple[QuantizedNote, ...]) -> None:
    """MVP renders one voice per part; overlapping onsets are rejected."""
    ordered = sorted(notes, key=lambda n: (n.start_beat, n.id))
    prev_end: Fraction | None = None
    prev_id: str | None = None
    for n in ordered:
        if prev_end is not None and n.start_beat < prev_end:
            raise NotationError(
                f"overlapping notes in one part are unsupported: {prev_id} ends at "
                f"{prev_end} but {n.id} starts at {n.start_beat}"
            )
        prev_end = n.start_beat + n.duration_beats
        prev_id = str(n.id)


def _build_part_measures(
    payload: ScoreRevisionPayload,
    part_notes: list[QuantizedNote],
    part_name: str,
    spans: list[_MeasureSpan],
    presentation: PitchSpace,
) -> stream.Part:
    beat_ql = _beat_ql(payload)
    part = stream.Part()
    part.partName = part_name
    if presentation is PitchSpace.WRITTEN_HORN_F:
        part.insert(0, instrument.Horn())

    tempo_marks: dict[int, list[tuple[Fraction, tempo.MetronomeMark]]] = {}
    for seg in payload.tempo_map:
        mark = tempo.MetronomeMark(number=seg.bpm)
        for idx, span in enumerate(spans):
            if span.start_beat <= seg.start_beat < span.end_beat:
                tempo_marks.setdefault(idx, []).append((seg.start_beat - span.start_beat, mark))
                break
        else:
            # Segment begins at/after the content end: keep the tempo
            # change by anchoring it to the end of the final measure.
            tempo_marks.setdefault(len(spans) - 1, []).append(
                (spans[-1].duration_beats, mark)
            )

    # Split every canonical note into measure-bound fragments once.
    pieces_by_measure: dict[int, list[tuple[QuantizedNote, int, int, Fraction, Fraction]]] = {}
    for n in part_notes:
        pieces = _note_pieces(n, spans)
        for pidx, (sidx, local_start, dur) in enumerate(pieces):
            pieces_by_measure.setdefault(sidx, []).append((n, pidx, len(pieces), local_start, dur))

    for idx, span in enumerate(spans):
        measure = stream.Measure(number=span.number)
        if span.implicit:
            # music21 maps MusicXML implicit="yes" to showNumber=NEVER.
            measure.showNumber = stream_enums.ShowNumber.NEVER

        if idx == 0:
            ks = payload.key_signature
            if presentation is PitchSpace.WRITTEN_HORN_F:
                ks = horn_f.written_key_signature(ks)
            measure.insert(0, key.KeySignature(ks.fifths))
            ts = payload.time_signature
            measure.insert(0, meter.TimeSignature(f"{ts.beats_per_measure}/{ts.beat_unit}"))
            measure.insert(0, clef.TrebleClef())

        for local_beat, mark in tempo_marks.get(idx, []):
            measure.insert(local_beat * beat_ql, mark)

        # Measure content: note fragments + gap rests, in beat order.
        events = sorted(pieces_by_measure.get(idx, []), key=lambda e: e[3])
        cursor = Fraction(0)
        span_dur = span.duration_beats
        for n, pidx, count, local_start, dur in events:
            if local_start > cursor:
                measure.insert(
                    cursor * beat_ql,
                    note.Rest(quarterLength=(local_start - cursor) * beat_ql),
                )
            m21_note = note.Note(quarterLength=dur * beat_ql)
            m21_note.pitch = pitch.Pitch(
                midi=horn_f.concert_to_written_midi(n.pitch_midi)
                if presentation is PitchSpace.WRITTEN_HORN_F
                else n.pitch_midi
            )
            m21_note.id = musicxml_note_id(n.id)
            n_tie = _tie_for(pidx, count, n)
            if n_tie is not None:
                m21_note.tie = n_tie
            measure.insert(local_start * beat_ql, m21_note)
            cursor = local_start + dur
        if cursor < span_dur:
            measure.insert(
                cursor * beat_ql,
                note.Rest(quarterLength=(span_dur - cursor) * beat_ql),
            )

        part.append(measure)
    return part


def build_music21_score(
    score: ScoreDocument,
    presentation: PitchSpace = PitchSpace.CONCERT,
) -> stream.Score:
    """Render *score* (canonical concert pitch) into a music21 ``Score``.

    ``presentation`` selects the export presentation: ``CONCERT`` renders
    sounding pitches verbatim; ``WRITTEN_HORN_F`` renders every part
    projected +P5 with the written key signature and Horn in F
    ``<transpose>`` metadata.
    """
    if score.pitch_space is not PitchSpace.CONCERT:
        raise NotationError("canonical ScoreDocument must be concert pitch")
    payload = score.payload
    spans = _measure_spans(payload)

    m21_score = stream.Score()
    if score.title:
        m21_score.insert(0, metadata.Metadata(title=score.title))

    for part in payload.parts:
        ordered = sorted(part.notes, key=lambda n: (n.start_beat, n.id))
        _check_monophonic(tuple(ordered))
        m21_score.append(
            _build_part_measures(payload, list(ordered), part.name, spans, presentation)
        )
    return m21_score
